def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (after '-')
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert to comparable form: (is_numeric, numeric_value_or_string)
            prerelease_comparable = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_comparable.append((0, int(identifier)))
                else:
                    prerelease_comparable.append((1, identifier))
        else:
            prerelease_comparable = None

        return (major, minor, patch, prerelease_comparable)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)

        # For sorting:
        # - Compare major, minor, patch numerically
        # - Version without pre-release sorts after version with pre-release
        #   (so we use False for no prerelease, True for has prerelease in the tuple,
        #    but we need to reverse: has prerelease should come first)
        # - Pre-release identifiers: all-digit before others, then by value
        # - If all shared identifiers equal, fewer sorts first
        # - Keep input order for equal precedence (use index as tiebreaker)

        if prerelease is None:
            # No pre-release: sort after same version with pre-release
            # Use (major, minor, patch, 1, (), index) where 1 means no prerelease
            return (major, minor, patch, 1, (), index)
        else:
            # Has pre-release: sort before same version without
            # Use (major, minor, patch, 0, prerelease_comparable, index)
            return (major, minor, patch, 0, tuple(prerelease), index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

